namespace CET6Word {
 public class Tests {
  static int passed,failed;static string root;static List<string> lines=new List<string>();
  static void Check(bool condition,string message="assertion failed"){if(!condition)throw new Exception(message);}
  static void Throws(Action action){bool thrown=false;try{action();}catch{thrown=true;}Check(thrown,"expected rejection");}
  static void Test(string name,Action action){try{action();passed++;Log("PASS "+name);}catch(Exception ex){failed++;Log("FAIL "+name+": "+ex.Message);}}
  static void Log(string text){Console.WriteLine(text);lines.Add(text);}
  static LearningEngine Engine(){return new LearningEngine(Program.CreateState(),123);}
  static string PathFor(string name){string dir=Path.Combine(root,name+"-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);return dir;}
  static byte[] Wave(){using(var m=new MemoryStream())using(var w=new BinaryWriter(m)){w.Write(Encoding.ASCII.GetBytes("RIFF"));w.Write(36+480);w.Write(Encoding.ASCII.GetBytes("WAVEfmt "));w.Write(16);w.Write((short)1);w.Write((short)1);w.Write(24000);w.Write(48000);w.Write((short)2);w.Write((short)16);w.Write(Encoding.ASCII.GetBytes("data"));w.Write(480);w.Write(new byte[480]);return m.ToArray();}}
  static Task<string[]> HttpOnce(TcpListener listener,int status) {return Task.Run(()=>{using(var client=listener.AcceptTcpClient())using(var stream=client.GetStream()){stream.ReadTimeout=8000;var header=new StringBuilder();while(!header.ToString().EndsWith("\r\n\r\n")){int value=stream.ReadByte();if(value<0 || header.Length>65536)throw new IOException("HTTP test header incomplete");header.Append((char)value);}string headers=header.ToString();if(headers.IndexOf("Expect: 100-continue",StringComparison.OrdinalIgnoreCase)>=0){var interim=Encoding.ASCII.GetBytes("HTTP/1.1 100 Continue\r\n\r\n");stream.Write(interim,0,interim.Length);}int length=Int32.Parse(headers.Split(new[]{"\r\n"},StringSplitOptions.None).Single(l=>l.StartsWith("Content-Length:",StringComparison.OrdinalIgnoreCase)).Split(':')[1].Trim());var body=new byte[length];int pos=0;while(pos<length){int n=stream.Read(body,pos,length-pos);if(n==0)throw new IOException("HTTP test body incomplete");pos+=n;}byte[] response=status==200?Wave():Encoding.UTF8.GetBytes("Unauthorized");byte[] responseHead=Encoding.ASCII.GetBytes("HTTP/1.1 "+status+(status==200?" OK":" Unauthorized")+"\r\nContent-Type: audio/wav\r\nContent-Length: "+response.Length+"\r\nConnection: close\r\n\r\n");stream.Write(responseHead,0,responseHead.Length);stream.Write(response,0,response.Length);return new[]{headers,Encoding.UTF8.GetString(body)};}});}
  static void Round(LearningEngine e,string id,string answer){e.EndSession();e.StartWith(new List<string>{id},false,"test");e.Submit(answer);e.Next();}
  static void Entry(ZipArchive z,string name,string value){using(var w=new StreamWriter(z.CreateEntry(name).Open(),new UTF8Encoding(false)))w.Write(value);}
  static IEnumerable<System.Windows.DependencyObject> Descendants(System.Windows.DependencyObject root){for(int i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(root);i++){var c=System.Windows.Media.VisualTreeHelper.GetChild(root,i);yield return c;foreach(var d in Descendants(c))yield return d;}}
  static string MakeXlsx(string dir,bool shared){string p=Path.Combine(dir,shared?"shared.xlsx":"inline.xlsx");using(var z=ZipFile.Open(p,ZipArchiveMode.Create)){
   Entry(z,"xl/workbook.xml","<workbook xmlns='http://schemas.openxmlformats.org/spreadsheetml/2006/main' xmlns:r='http://schemas.openxmlformats.org/officeDocument/2006/relationships'><sheets><sheet name='Vocabulary' sheetId='1' r:id='rId1'/></sheets></workbook>");
   Entry(z,"xl/_rels/workbook.xml.rels","<Relationships xmlns='http://schemas.openxmlformats.org/package/2006/relationships'><Relationship Id='rId1' Target='worksheets/sheet1.xml'/></Relationships>");
   if(shared){Entry(z,"xl/sharedStrings.xml","<sst xmlns='http://schemas.openxmlformats.org/spreadsheetml/2006/main'><si><t>word</t></si><si><t>meaning</t></si><si><r><t>re</t></r><r><t>liable</t></r></si><si><t>可靠的</t></si></sst>");Entry(z,"xl/worksheets/sheet1.xml","<worksheet xmlns='http://schemas.openxmlformats.org/spreadsheetml/2006/main'><sheetData><row r='1'><c r='A1' t='s'><v>0</v></c><c r='C1' t='s'><v>1</v></c></row><row r='2'><c r='A2' t='s'><v>2</v></c><c r='C2' t='s'><v>3</v></c></row></sheetData></worksheet>");}
   else Entry(z,"xl/worksheets/sheet1.xml","<worksheet xmlns='http://schemas.openxmlformats.org/spreadsheetml/2006/main'><sheetData><row r='1'><c r='A1' t='inlineStr'><is><t>word</t></is></c><c r='B1' t='inlineStr'><is><t>meaning</t></is></c></row><row r='2'><c r='A2' t='inlineStr'><is><t>adapt</t></is></c><c r='B2' t='inlineStr'><is><t>适应</t></is></c></row></sheetData></worksheet>");
  }return p;}
  [STAThread] public static int Main(string[] args){Console.OutputEncoding=Encoding.UTF8;root=args[0];Directory.CreateDirectory(root);
   Test("V2 formal corpus: 2800–3200 unique words with all six fields",()=>{var e=Engine();Check(e.Current.Words.Count>=2800&&e.Current.Words.Count<=3200);Check(e.Current.Words.Select(w=>w.English).Distinct().Count()==e.Current.Words.Count);Check(e.Current.Words.All(w=>w.Formal && !String.IsNullOrEmpty(w.PartOfSpeech)&&!String.IsNullOrEmpty(w.UsIpa)&&w.Examples.Count>=1&&w.Examples.All(x=>!String.IsNullOrWhiteSpace(x.Chinese))));StateStore.Validate(e.State);});
   Test("first-run defaults: translation and automatic reading off",()=>{var e=Engine();Check(!e.State.Settings.Translation && !e.State.Settings.AutoRead);Check(e.Position.Mode=="fixed" && e.State.Settings.ErrorThreshold==2);});
   Test("expansion: hidden > meaning > example > hidden",()=>{int n=0;n=Policy.NextExpansion(n,false);Check(n==1);n=Policy.NextExpansion(n,false);Check(n==2);Check(Policy.NextExpansion(n,false)==0);});
   Test("global translation does not force examples",()=>{Check(Policy.NextExpansion(0,true)==2);Check(Policy.NextExpansion(2,true)==0);var e=Engine();var row=new WordView{Word=e.Current.Words[0],Engine=e,Global=true};Check(row.MeaningVisibility==System.Windows.Visibility.Visible && row.ExampleVisibility==System.Windows.Visibility.Collapsed);});
   Test("passive browsing has no learned candidates",()=>{var e=Engine();e.StudyWords();Check(e.Candidates("learned").Count==0);});
   Test("active learning deduplicates and uses latest expansion time",()=>{var e=Engine();var a=e.Current.Words[0];var b=e.Current.Words[1];e.Learn(a.Id);e.Learn(b.Id);e.Learn(a.Id);var ids=e.Candidates("recent");Check(ids.Count==2 && ids[0]==a.Id && e.GetProgress(a.Id).LearnCount==2);});
   Test("mastering removes word and restoring preserves original order",()=>{var e=Engine();var w=e.Current.Words[0];e.Master(w.Id,true);Check(!e.StudyWords().Any(x=>x.Id==w.Id));Check(e.Current.Words.Count==2955);e.Master(w.Id,false);Check(e.StudyWords()[0].Id==w.Id);});
   Test("favorites toggle and do not move anchor or count as study",()=>{var e=Engine();var w=e.Current.Words[10];e.SetAnchor(w.Id);e.ToggleFavorite(w.Id);Check(e.Favorite(w.Id)&&e.Anchor==w.Id&&e.Candidates("recent").Count==0);e.ToggleFavorite(w.Id);Check(!e.Favorite(w.Id));});
   Test("one word belongs to multiple books; deleting book keeps word",()=>{var e=Engine();var w=e.Current.Words[0];var a=e.AddNotebook("A");var b=e.AddNotebook("B");e.PutInNotebook(a,w.Id);e.PutInNotebook(b,w.Id);e.PutInNotebook(b,w.Id);Check(a.Words.Count==1 && b.Words.Count==1);e.DeleteNotebook(a);Check(e.Find(w.Id)==w && b.Words.Count==1);});
   Test("default book protected; duplicate and blank names rejected",()=>{var e=Engine();Throws(()=>e.DeleteNotebook(e.State.Notebooks[0]));Throws(()=>e.RenameNotebook(e.State.Notebooks[0],"X"));Throws(()=>e.AddNotebook(" "));e.AddNotebook("A");Throws(()=>e.AddNotebook("A"));});
   Test("random order is a permutation and survives serialization",()=>{var e=Engine();e.Sort("random",e.Current.Words[20].Id);var ids=e.StudyWords().Select(w=>w.Id).ToList();Check(ids.Distinct().Count()==2955);Check(!ids.SequenceEqual(e.Current.Words.Select(w=>w.Id)));var after=new LearningEngine(StateStore.Decode(StateStore.Encode(e.State)));Check(after.StudyWords().Select(w=>w.Id).SequenceEqual(ids));Check(after.Anchor==e.Anchor && after.Position.Mode=="random");});
   Test("fixed sorting returns source order and maps anchor",()=>{var e=Engine();var id=e.Current.Words[35].Id;e.Sort("random",id);e.Sort("fixed",id);Check(e.StudyWords().Select(w=>w.Id).SequenceEqual(e.Current.Words.Select(w=>w.Id)));Check(e.Anchor==id);});
   Test("quiz ranges: all, learned, named notebook",()=>{var e=Engine();string id=e.Current.Words[0].Id;e.Learn(id);e.Master(id,true);e.ToggleFavorite(id);Check(e.Candidates("all").Count==e.Current.Words.Count);Check(e.Candidates("learned").SequenceEqual(new[]{id}));Check(e.Candidates("default").SequenceEqual(new[]{id}));});
   Test("recent X uses actual available size; empty and invalid sizes rejected",()=>{var e=Engine();Throws(()=>e.Start("recent",5,false,true));e.Learn(e.Current.Words[0].Id);var s=e.Start("recent",10,false,true);Check(s.Words.Count==1);e.EndSession();Throws(()=>e.Start("all",0,false));});
   Test("Chinese and listening quiz retain prompt setting",()=>{var e=Engine();var s=e.Start("all",2,true);Check(s.Listening && s.Words.Count==2 && s.Words.Distinct().Count()==2);e.EndSession();Check(!e.Start("all",2,false).Listening);});
   Test("wrong answer creates separate error, reveals spelling data, no favorite",()=>{var e=Engine();var id=e.Current.Words[0].Id;e.StartWith(new List<string>{id},false,"test");var a=e.Submit("wrong");Check(!a.Correct && e.State.Errors[id].Pending && !e.Favorite(id));Check(e.Question.English=="abandon");Throws(()=>e.Submit("abandon"));});
   Test("grading normalizes case and outer whitespace only",()=>{Check(Policy.AnswerMatches("adapt"," ADAPT "));Check(!Policy.AnswerMatches("adapt","adapts"));Check(!Policy.AnswerMatches("adapt","ad apt"));var e=Engine();e.Start("all",1,false);Throws(()=>e.Submit("   "));});
   Test("submitted feedback and unsubmitted next question survive reload",()=>{var e=Engine();e.Start("all",2,true);string id=e.Question.Id;e.Submit("wrong");var a=new LearningEngine(StateStore.Decode(StateStore.Encode(e.State)));Check(a.Active.AwaitingNext && a.Question.Id==id);Check(a.Next());var b=new LearningEngine(StateStore.Decode(StateStore.Encode(a.State)));Check(!b.Active.AwaitingNext && b.Active.Attempts.Count==1 && b.Question.Id==b.Active.Words[1]);});
   Test("results count errors; retries include only this round's wrong words",()=>{var e=Engine();var s=e.Start("all",2,false);string wrong=e.Question.Id;e.Submit("wrong");e.Next();e.Submit(e.Question.English);e.Next();Check(s.Finished>0&&s.Attempts.Count(a=>a.Correct)==1&&e.Wrong(s).SequenceEqual(new[]{wrong}));e.EndSession();Check(e.StartWith(e.Wrong(s),s.Listening,"retry").Words.Count==1);});
   Test("default two correct removes pending error but keeps history",()=>{var e=Engine();var w=e.Current.Words[0];Round(e,w.Id,"wrong");Round(e,w.Id,w.English);Check(e.State.Errors[w.Id].Pending && e.State.Errors[w.Id].Streak==1);Round(e,w.Id,w.English);Check(!e.State.Errors[w.Id].Pending && e.State.Errors[w.Id].WrongCount==1 && e.State.Errors[w.Id].PracticeCount==3 && e.State.Sessions.Count==3);});
   Test("custom threshold and correct-wrong-correct reset streak",()=>{var e=Engine();var w=e.Current.Words[0];e.State.Settings.ErrorThreshold=3;Round(e,w.Id,"wrong");Round(e,w.Id,w.English);Round(e,w.Id,"wrong");Round(e,w.Id,w.English);Check(e.State.Errors[w.Id].Streak==1 && e.State.Errors[w.Id].Pending && e.State.Errors[w.Id].WrongCount==2);});
   Test("manual error remove and restore preserve attempts and wrong count",()=>{var e=Engine();var w=e.Current.Words[0];Round(e,w.Id,"wrong");e.Review(w.Id,false);Check(!e.State.Errors[w.Id].Pending);e.Review(w.Id,true);Check(e.State.Errors[w.Id].Pending && e.State.Errors[w.Id].WrongCount==1 && e.State.Sessions[0].Attempts.Count==1);});
   Test("CSV: BOM aliases quoted commas escaped quotes multiline example",()=>{var rows=VocabularyImport.ParseCsv("\uFEFF单词,释义,例句\r\nadapt,\"适应,调整\",\"They say \"\"adapt\"\".\nThen act.\"\r\n");var r=VocabularyImport.FromRows(rows,"Test");Check(r.Vocabulary.Words[0].Meaning=="适应,调整");Check(r.Vocabulary.Words[0].Examples[0].English.Contains("\"adapt\""));});
   Test("CSV: duplicates rejected rows missing examples reported",()=>{var r=VocabularyImport.FromRows(VocabularyImport.ParseCsv("word,meaning\nadapt,适应\nADAPT,调整\n,空词\nreliable,可靠\n"),"Test");Check(r.Vocabulary.Words.Count==2 && r.Duplicates==1 && r.Rejected.Count==1 && r.MissingExamples==2);});
   Test("CSV: malformed quoting missing columns and empty data rejected",()=>{Throws(()=>VocabularyImport.ParseCsv("word,meaning\n\"adapt,适应"));Throws(()=>VocabularyImport.ParseCsv("a\"b,c"));Throws(()=>VocabularyImport.FromRows(VocabularyImport.ParseCsv("a,b\nx,y"),"x"));Throws(()=>VocabularyImport.FromRows(VocabularyImport.ParseCsv("word,meaning\n,\n"),"x"));});
   Test("CSV: UTF8 and GB18030 files import correctly",()=>{string d=PathFor("csv");string p=Path.Combine(d,"test.csv");File.WriteAllText(p,"word,meaning\nadapt,适应",new UTF8Encoding(true));Check(VocabularyImport.Read(p).Vocabulary.Words[0].Meaning=="适应");File.WriteAllText(p,"word,meaning\nadapt,适应",Encoding.GetEncoding("GB18030"));Check(VocabularyImport.Read(p).Vocabulary.Words[0].Meaning=="适应");});
   Test("XLSX: inline strings and shared rich strings with sparse columns",()=>{string d=PathFor("xlsx");Check(VocabularyImport.Read(MakeXlsx(d,false)).Vocabulary.Words[0].English=="adapt");var r=VocabularyImport.Read(MakeXlsx(d,true));Check(r.Vocabulary.Words[0].English=="reliable" && r.Vocabulary.Words[0].Meaning=="可靠的");});
   Test("imported same-spelling word has independent progress and positions",()=>{var e=Engine();var r=VocabularyImport.FromRows(VocabularyImport.ParseCsv("word,meaning\nabandon,放弃"),"Other");var original=e.Current;e.Master(original.Words[0].Id,true);e.SetAnchor(original.Words[10].Id);e.State.Vocabularies.Add(r.Vocabulary);e.State.CurrentVocabulary=r.Vocabulary.Id;Check(!e.GetProgress(r.Vocabulary.Words[0].Id).Mastered && e.Anchor==null);e.State.CurrentVocabulary=original.Id;Check(e.GetProgress(original.Words[0].Id).Mastered && e.Anchor==original.Words[10].Id);});
   Test("atomic save and reopen preserve learned/mastered/books/random/threshold",()=>{string d=PathFor("save");string expected;using(var store=new StateStore(d)){var e=new LearningEngine(store.Load(Program.CreateState));var w=e.Current.Words[30];e.Learn(w.Id);e.Master(w.Id,true);e.ToggleFavorite(w.Id);e.PutInNotebook(e.AddNotebook("重点"),w.Id);e.Sort("random",e.Current.Words[40].Id);e.State.Settings.AutoRead=true;e.State.Settings.ErrorThreshold=4;store.Save(e.State);expected=StateStore.Encode(e.State);}using(var store=new StateStore(d))Check(StateStore.Equivalent(StateStore.Encode(store.Load(Program.CreateState)),expected));});
   Test("single-instance lock prevents concurrent writers",()=>{string d=PathFor("lock");using(var a=new StateStore(d)){Throws(()=>{using(var b=new StateStore(d)){};});}});
   Test("corrupt main recovers previous valid state and preserves damaged file",()=>{string d=PathFor("recovery");using(var store=new StateStore(d)){var s=store.Load(Program.CreateState);s.Settings.AutoRead=true;store.Save(s);File.WriteAllText(store.FilePath,"broken");var restored=store.Load(Program.CreateState);Check(!restored.Settings.AutoRead && store.RecoveryNotice!=null && Directory.GetFiles(d,"damaged-*").Length==1);}});
   Test("unrecoverable corruption never silently resets data",()=>{string d=PathFor("corrupt");using(var store=new StateStore(d)){File.WriteAllText(store.FilePath,"broken");Throws(()=>store.Load(Program.CreateState));Check(File.ReadAllText(store.FilePath)=="broken");}});
   Test("full backup restores exact complete state into a new directory",()=>{var e=Engine();var w=e.Current.Words[2];e.Learn(w.Id);e.Master(w.Id,true);e.ToggleFavorite(w.Id);e.PutInNotebook(e.AddNotebook("重点"),w.Id);e.Sort("random",e.Current.Words[12].Id);e.State.Settings.AutoRead=true;Round(e,w.Id,"wrong");string original=StateStore.Encode(e.State),backup=Path.Combine(PathFor("export"),"test.cet6backup");using(var store=new StateStore(PathFor("source"))){store.Save(e.State);store.Export(backup,e.State);}using(var dest=new StateStore(PathFor("destination"))){dest.Load(Program.CreateState);dest.Restore(dest.ReadBackup(backup));Check(StateStore.Equivalent(StateStore.Encode(dest.Load(Program.CreateState)),original),"backup changed field values or array order");Check(Directory.GetFiles(dest.DirectoryPath,"before-restore-*").Length==1);}});
   Test("backup tamper and invalid word references rejected without changing state",()=>{string d=PathFor("tamper");using(var store=new StateStore(d)){var state=store.Load(Program.CreateState);string p=Path.Combine(d,"test.cet6backup");store.Export(p,state);var b=StateStore.Json().Deserialize<BackupEnvelope>(File.ReadAllText(p));b.Data=b.Data.Replace("abandon","wrong");File.WriteAllText(p,StateStore.Json().Serialize(b));Throws(()=>store.ReadBackup(p));Check(store.Load(Program.CreateState).Vocabularies[0].Words[0].English=="abandon");state.Notebooks[0].Words.Add("nonexistent");Throws(()=>store.Save(state));}});
   Test("unsupported schema and invalid session order rejected",()=>{var e=Engine();e.State.SchemaVersion=3;Throws(()=>StateStore.Validate(e.State));e.State.SchemaVersion=1;var s=e.Start("all",2,false);s.Attempts.Add(new Attempt{WordId=s.Words[1],Answer="wrong"});Throws(()=>StateStore.Validate(e.State));});
   Test("encrypted speech key roundtrip and backup excludes plaintext secret",()=>{string d=PathFor("key");using(var store=new StateStore(d)){const string secret="TEST-KEY-NOT-REAL-9876";store.SaveKey(secret);Check(store.ReadKey()==secret);Check(!Encoding.UTF8.GetString(File.ReadAllBytes(Path.Combine(d,"speech-key.bin"))).Contains(secret));string p=Path.Combine(d,"backup");store.Export(p,Program.CreateState());Check(!File.ReadAllText(p).Contains(secret));}});
   Test("online WAV is cached; next playback avoids provider request",()=>{using(var store=new StateStore(PathFor("online")))using(var speech=new SpeechService(store,()=>new Preferences())){int online=0,played=0;speech.OnlineOverride=t=>{online++;return Wave();};speech.OfflineOverride=t=>{throw new Exception("should not fallback");};speech.PlaybackOverride=b=>played++;speech.SpeakAsync("adapt").Wait();speech.SpeakAsync("adapt").Wait();Check(online==1 && played==2);}});
   Test("Azure adapter real HTTP: correct endpoint, auth, US voice, SSML, WAV cache",()=>{var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();try{int port=((IPEndPoint)listener.LocalEndpoint).Port;var server=HttpOnce(listener,200);using(var store=new StateStore(PathFor("azure-http")))using(var speech=new SpeechService(store,()=>new Preferences{AzureRegion="eastus"})){store.SaveKey("TEST-KEY-ONLY");int requests=0,plays=0;speech.OnlineRequestFactory=url=>{Check(url=="https://eastus.tts.speech.microsoft.com/cognitiveservices/v1");requests++;var r=(HttpWebRequest)WebRequest.Create("http://127.0.0.1:"+port+"/cognitiveservices/v1");r.Proxy=null;return r;};speech.PlaybackOverride=b=>{Check(SpeechService.WaveValid(b));plays++;};Check(speech.SpeakAsync("Fish & chips <review>").Result=="在线美音");var request=server.Result;Check(request[0].StartsWith("POST /cognitiveservices/v1 HTTP/1.1"));Check(request[0].Contains("Ocp-Apim-Subscription-Key: TEST-KEY-ONLY"));Check(request[0].Contains("X-Microsoft-OutputFormat: riff-24khz-16bit-mono-pcm"));Check(request[1].Contains("en-US-JennyNeural") && request[1].Contains("rate='0%'") && request[1].Contains("Fish &amp; chips &lt;review&gt;"));speech.SpeakAsync("Fish & chips <review>").Wait();Check(requests==1 && plays==2);}}finally{listener.Stop();}});
   Test("Azure adapter real HTTP unauthorized response falls back locally",()=>{var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();try{int port=((IPEndPoint)listener.LocalEndpoint).Port;var server=HttpOnce(listener,401);using(var store=new StateStore(PathFor("azure-fallback")))using(var speech=new SpeechService(store,()=>new Preferences{AzureRegion="eastus"})){store.SaveKey("INVALID-TEST-KEY");speech.OnlineRequestFactory=url=>{var r=(HttpWebRequest)WebRequest.Create("http://127.0.0.1:"+port+"/cognitiveservices/v1");r.Proxy=null;return r;};int local=0,plays=0;speech.OfflineOverride=text=>{local++;return Wave();};speech.PlaybackOverride=b=>plays++;Check(speech.SpeakAsync("adapt").Result.Contains("本地美音"));server.Wait();Check(local==1 && plays==1);}}finally{listener.Stop();}});
   Test("online failure falls back to cached local US WAV",()=>{using(var store=new StateStore(PathFor("offline")))using(var speech=new SpeechService(store,()=>new Preferences())){int local=0,played=0;speech.OnlineOverride=t=>{throw new IOException("offline");};speech.OfflineOverride=t=>{local++;return Wave();};speech.PlaybackOverride=b=>played++;Check(speech.SpeakAsync("adapt").Result.Contains("本地美音"));speech.SpeakAsync("adapt").Wait();Check(local==1 && played==2);}});
   Test("invalid online audio falls back; absent voice returns explicit failure",()=>{using(var store=new StateStore(PathFor("audio-invalid")))using(var speech=new SpeechService(store,()=>new Preferences())){speech.OnlineOverride=t=>Encoding.UTF8.GetBytes("html error");speech.OfflineOverride=t=>Wave();speech.PlaybackOverride=b=>{};Check(speech.SpeakAsync("adapt").Result.Contains("本地"));speech.OfflineOverride=t=>{throw new InvalidOperationException("系统没有可用的美式英语语音");};Check(speech.SpeakAsync("new text").Result.Contains("没有可用"));}});
   Test("real Windows en-US speech synthesizes a valid WAV",()=>{using(var synth=new SpeechSynthesizer()){Log("Installed voices: "+String.Join(", ",synth.GetInstalledVoices().Select(v=>v.VoiceInfo.Name+"/"+v.VoiceInfo.Culture.Name+"/enabled="+v.Enabled)));try{synth.SelectVoice("Microsoft Zira Desktop");using(var m=new MemoryStream()){synth.SetOutputToWaveStream(m);synth.Speak("Practice");Log("STA voice bytes="+m.Length);}}catch(Exception ex){Log("STA voice error="+ex.ToString());}}using(var store=new StateStore(PathFor("real-audio")))using(var speech=new SpeechService(store,()=>new Preferences())){speech.OnlineOverride=t=>{throw new IOException("test offline");};int played=0;speech.PlaybackOverride=b=>{Check(SpeechService.WaveValid(b));played++;};string result=speech.SpeakAsync("Learning takes practice.").Result;Check(played==1,result);}});
   Test("unsafe online region rejected; cache keys separate region and text",()=>{Check(SpeechService.RegionValid("eastus"));Check(!SpeechService.RegionValid("x/path"));Check(!SpeechService.RegionValid("https://host"));using(var store=new StateStore(PathFor("cache-key")))using(var s=new SpeechService(store,()=>new Preferences())){Check(s.CacheFile("a","azure:eastus")!=s.CacheFile("a","windows-en-US"));Check(s.CacheFile("a","x")!=s.CacheFile("b","x"));}});
   V2Tests.Run(Test,root);
   UITests.Run(Test,root);
   Log("RESULT: "+passed+" passed, "+failed+" failed");File.WriteAllLines(Path.Combine(root,"results.txt"),lines,new UTF8Encoding(false));return failed==0?0:1;
  }
 }
